-- Safe bitwise XOR function compatible with all Luau environments
local function safeXor(n1, n2)
    local res = 0
    for i = 0, 31 do
        local b1 = (n1 / 2^i) % 2 >= 1 and 1 or 0
        local b2 = (n2 / 2^i) % 2 >= 1 and 1 or 0
        if b1 ~= b2 then
